#!/usr/bin/env node
/**
 * E04-03 · BOOP human-control surfaces in jsdom (client half).
 *
 * ⚠️ ALL HOST DATA IN THIS FILE IS FIXTURE DATA — NOT LIVE HOST DATA.
 * Shapes are copied from the Host half's contract fixtures
 * (`.work/control-fixtures.json`, generated by e04-02-host from the real
 * `boopControl` implementation; contract by task-9). Passing these tests does
 * NOT prove G04/G05/G09 on a real host/browser.
 *
 * Proves the client promises that must hold without a browser:
 *  - approval cards show the exact binding (payloadHash/taskVersion/policyEpoch/
 *    nonce), valid vs expired/version-moved/epoch-moved/already-handled states,
 *    and the buttons follow the server's `canDecide` (FE-06/AT-28);
 *  - a decision is stated as record-only after the server receipt
 *    (`accepted`+`outcome`, `executed:false`, `dispatched:false`); an idempotent
 *    `already-handled` reply is neutral; an APPROVAL_STALE refusal keeps its
 *    exact code/cause and nothing is optimistically flipped;
 *  - Stop is scoped and deterministic: the three Host buckets
 *    (stopped/refused/unknown) keep distinct meaning, per-item partial success
 *    is itemised, `noop` reads 无可停止内容 (never success), and Stop still works
 *    when the control read failed; the permanent strip says
 *    "请求已发送 ≠ 外部副作用已撤销" (FE-07/AT-30);
 *  - recovery release has no default selection and no select-all; only checked
 *    messageIds are sent, unknown ids are reported, and the Host's
 *    `runtimeEnforcement.composed:false` is displayed honestly (G04/AT-26);
 *  - unreadable/unknown/stale/partial states are honest (FE-11); stale reads
 *    (request sequence or Host projectionSeq) never overwrite newer state;
 *  - keyboard/focus/accessibility, scoped styles + unmount cleanup (TB08/FE-09/
 *    FE-12), plain text (no HTML/Markdown), single external React (TB02).
 *
 * Run: node --test --test-force-exit tests/client/e04-03-control.test.mjs
 */
import assert from 'node:assert/strict'
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import { test, before, after } from 'node:test'
import React from 'react'
import {
  BoopApprovalBadge,
  BoopControlPanel,
  buildDecisionRequest,
  buildReleaseRequest,
  buildStopRequest,
} from '../../lib/control.test.bundle.cjs'

let dir
let window
let document
/** Imported AFTER the jsdom globals exist (react-dom decides canUseDOM at load). */
let createRoot

before(async () => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'boop-e04-03-'))
  const { JSDOM } = await import('jsdom')
  const dom = new JSDOM('<!doctype html><html><body></body></html>', {
    pretendToBeVisual: true,
    url: 'http://localhost/',
  })
  window = dom.window
  document = dom.window.document
  globalThis.window = window
  globalThis.document = document
  ;({ createRoot } = await import('react-dom/client'))
})

after(() => {
  fs.rmSync(dir, { recursive: true, force: true })
})

const tick = (ms = 80) => new Promise((resolve) => setTimeout(resolve, ms))

async function waitFor(condition, what = 'condition', timeout = 5000) {
  const start = Date.now()
  while (Date.now() - start < timeout) {
    if (condition()) return
    await tick(20)
  }
  throw new Error(`timed out waiting for ${what}`)
}

const click = (element) => {
  assert.ok(element, 'expected element to click')
  element.click()
}

function setNativeValue(element, value) {
  const proto = element instanceof window.HTMLSelectElement
    ? window.HTMLSelectElement.prototype
    : window.HTMLInputElement.prototype
  Object.getOwnPropertyDescriptor(proto, 'value').set.call(element, value)
  element.dispatchEvent(new window.Event(element.tagName === 'SELECT' ? 'change' : 'input', { bubbles: true }))
}

async function renderControl(call, props = {}, until) {
  const host = document.createElement('div')
  document.body.appendChild(host)
  const root = createRoot(host)
  root.render(React.createElement(BoopControlPanel, { call, ...props }))
  await waitFor(until ?? (() => host.querySelector('[data-boop-control-state="ready"], [data-boop-control-alert]')), 'control panel')
  await tick(40)
  return {
    host,
    text: () => host.textContent ?? '',
    approval: (id) => host.querySelector(`[data-boop-approval][data-approval-id="${id}"]`),
    cleanup: () => {
      root.unmount()
      host.remove()
    },
  }
}

