test('E04-03 Stop all itemises the three buckets and never claims the side effects were undone (FE-07)', async () => {
  const opened = []
  const { call, calls } = makeCall({
    'boopControl/stop': () => ({
      ok: true,
      value: stopPartial({
        unknown: [
          {
            actionId: 'b_act_3',
            taskId: 'T3',
            targetSessionId: 'sess-unknown',
            actionState: 'running',
            outboxState: 'unknown',
            bucket: 'unknown',
            code: 'OUTCOME_UNKNOWN',
            reason: '投递结果未知',
            note: '不重试，等人工核查',
          },
        ],
        matched: 3,
        summary: { matched: 3, stopped: 1, refused: 1, unknown: 1 },
        truncated: true,
      }),
    }),
  })
  const view = await renderControl(call, { onOpenSession: (id) => opened.push(id) })
  click(view.host.querySelector('[data-boop-stop-action="stop"]'))
  await waitFor(() => view.host.querySelector('[data-boop-stop-result]'), 'stop result')

  const stopCall = calls.find((entry) => entry.endpoint === 'boopControl/stop')
  assert.deepEqual(stopCall.args, { request: { scope: 'all' } })

  const result = view.host.querySelector('[data-boop-stop-result]')
  assert.equal(result.getAttribute('data-accepted'), 'true')
  assert.match(result.textContent, /匹配 3 项：已停止 1，未停止 1，待确认 1/)
  assert.match(result.textContent, /已停止（BOOP 尚未投递的待发动作\/outbox 已取消）/)
  assert.match(result.textContent, /b_act_1：已停止（awaiting_approval → stopped；outbox prepared → cancelled）/)
  assert.match(result.textContent, /未停止（已投递或已终结：BOOP 不宣称撤销，请到原会话用原生 Stop）/)
  assert.match(result.textContent, /b_act_2：未停止（accepted｜ALREADY_DELIVERED）/)
  assert.match(result.textContent, /如仍在运行，请在原 Session 用原生 Stop 停止/)
  assert.match(result.textContent, /结果待确认（不重试、不显示为已停止）/)
  assert.match(result.textContent, /b_act_3：结果待确认（OUTCOME_UNKNOWN）/)
  assert.match(result.textContent, /请求已发送 ≠ 外部副作用已撤销/)
  assert.match(result.textContent, /动作读取到达上限（部分范围）：还有未覆盖的动作/)
  assert.match(result.textContent, /外部副作用已撤销=否/)
  assert.match(result.textContent, /用户 turn 被停=否/)
  assert.match(result.textContent, /审计：ledger，已记录/)
  assert.doesNotMatch(result.textContent, /已撤销成功|副作用已回滚|全部已撤销/, 'a stop request is not an undo claim')

  // The refused delivered action points the human at the original Session.
  click(result.querySelector('[data-boop-stop-action="open-session"]'))
  assert.deepEqual(opened, ['sess-verify'])
  view.cleanup()
})

