test('E04-03 recovery release has no default selection, no select-all, and reports the runtime gap (G04/AT-26)', async () => {
  let stateReads = 0
  const { call, calls } = makeCall({
    'boopControl/state': () => {
      stateReads += 1
      return { ok: true, value: controlState() }
    },
    'boopControl/release': () => ({
      ok: true,
      value: releaseFacts({ requestedMessageIds: ['msg-gate-1'], ignored: [] }),
    }),
  })
  const view = await renderControl(call)

  const entries = [...view.host.querySelectorAll('[data-boop-recovery-entry]')]
  assert.equal(entries.length, 3)
  for (const entry of entries) {
    const checkbox = entry.querySelector('input[type="checkbox"]')
    assert.equal(checkbox.checked, false, 'nothing is pre-selected / auto-approved')
    assert.ok(checkbox.getAttribute('aria-label'), 'every release checkbox is labelled')
  }
  const releasedEntry = view.host.querySelector('[data-boop-recovery-entry][data-message-id="msg-gate-3"]')
  assert.ok(releasedEntry.querySelector('input').disabled, 'already-released entries cannot be re-released')
  assert.equal(view.host.querySelector('[data-boop-recovery-action="release"]').disabled, true, 'release is disabled with 0 selected')
  assert.match(view.text(), /没有默认选中任何条目/)
  assert.match(view.text(), /运行时前置门控未接线：释放只改变门禁账本/)
  assert.match(view.text(), /待释放 2 条，已释放 1 条/)
  for (const button of view.host.querySelectorAll('button')) {
    assert.doesNotMatch(button.textContent, /全选|一键放行|全部释放/, 'no bulk release control')
  }

  click(entries[0].querySelector('input[type="checkbox"]'))
  await tick(30)
  const releaseButton = view.host.querySelector('[data-boop-recovery-action="release"]')
  assert.equal(releaseButton.disabled, false)
  assert.match(releaseButton.textContent, /释放选中（1）/)
  click(releaseButton)
  await waitFor(() => view.host.querySelector('[data-boop-release-result]'), 'release receipt')

  const releaseCall = calls.find((entry) => entry.endpoint === 'boopControl/release')
  assert.deepEqual(releaseCall.args, { request: { messageIds: ['msg-gate-1'] } }, 'only the checked messageId is released')
  const receipt = view.host.querySelector('[data-boop-release-result]')
  assert.match(receipt.textContent, /请求释放 1 项，已释放 1 项（msg-gate-1）/)
  assert.match(receipt.textContent, /忽略 0 项/)
  assert.match(receipt.textContent, /未勾选的条目仍保持阻断，没有自动放行/)
  assert.match(receipt.textContent, /审计：ledger，已记录/)
  assert.ok(stateReads >= 2, 'the entries are re-read after a release')
  view.cleanup()
})

