test('E04-03 an older control response never overwrites newer state (AT-19/FE-04)', async () => {
  const responses = []
  const { call } = makeCall({
    'boopControl/state': () => {
      const request = deferred()
      responses.push(request)
      return request.promise
    },
  })
  const view = await renderControl(call, {}, () => responses.length >= 1)
  window.dispatchEvent(new window.Event('online'))
  await waitFor(() => responses.length === 2, 'second state read')

  responses[1].resolve({
    ok: true,
    value: controlState({ projectionSeq: 12, pendingApprovals: [approval({ approvalId: 'a_new' })] }),
  })
  await waitFor(() => view.text().includes('a_new'), 'newer state')
  responses[0].resolve({
    ok: true,
    value: controlState({ projectionSeq: 11, pendingApprovals: [approval({ approvalId: 'a_old' })] }),
  })
  await tick(120)
  assert.match(view.text(), /a_new/, 'the newer response stays')
  assert.doesNotMatch(view.text(), /a_old/, 'the older response is discarded')
  assert.ok(view.host.querySelector('[data-boop-control-stale]'), 'the discard is announced, not silent')
  view.cleanup()
})

